export class KinematicAnimator {
    constructor(physics: any);
    physics: any;
    targets: Map<any, any>;
    animations: Map<any, any>;
    /**
     * Get or create animation target for a kinematic body
     * @param {number} bodyIndex - Index of the kinematic body
     * @returns {Object} Target object with px, py, pz, qx, qy, qz, qw properties
     */
    _getOrCreateTarget(bodyIndex: number): any;
    /**
     * Build animation properties from position/rotation config
     * Also initializes target with `from` values and writes to SAB
     * @private
     */
    private _buildProps;
    /**
     * Write animation target values to SharedArrayBuffer
     * @private
     */
    private _writeToSAB;
    /**
     * Basic from/to animation for a kinematic body
     *
     * @param {number} bodyIndex - Index of the kinematic body
     * @param {Object} config - Animation configuration
     * @param {Object} [config.position] - Position animation { from: [x,y,z], to: [x,y,z] }
     * @param {Object} [config.rotation] - Quaternion animation { from: [x,y,z,w], to: [x,y,z,w] }
     * @param {number} config.duration - Animation duration in milliseconds
     * @param {string} [config.ease='inOutQuad'] - Easing function name
     * @param {boolean|number} [config.loop=false] - Loop animation (true for infinite, number for count)
     * @param {boolean} [config.alternate=false] - Alternate direction on loop (ping-pong)
     * @returns {Object} Anime.js animation instance
     *
     * @example
     * // Horizontal sliding platform
     * animator.animate(platformIndex, {
     *   position: { from: [0, 1, 0], to: [5, 1, 0] },
     *   duration: 2000,
     *   ease: 'inOutQuad',
     *   loop: true,
     *   alternate: true
     * });
     */
    animate(bodyIndex: number, { position, rotation, duration, ease, loop, alternate }: {
        position?: any;
        rotation?: any;
        duration: number;
        ease?: string;
        loop?: boolean | number;
        alternate?: boolean;
    }): any;
    /**
     * Keyframe animation for a kinematic body
     *
     * @param {number} bodyIndex - Index of the kinematic body
     * @param {Object} keyframes - Property keyframes object
     * @param {Object} [options] - Animation options
     * @param {boolean|number} [options.loop=false] - Loop animation
     * @param {boolean} [options.alternate=false] - Alternate on loop
     * @returns {Object} Anime.js animation instance
     *
     * @example
     * // Multi-point path
     * animator.keyframes(platformIndex, {
     *   px: [
     *     { to: 0, duration: 0 },
     *     { to: 5, duration: 1000, ease: 'outQuad' },
     *     { to: 5, duration: 800 },
     *     { to: 0, duration: 1200 }
     *   ],
     *   py: [
     *     { to: 2, duration: 0 },
     *     { to: 3, duration: 1000 },
     *     { to: 3, duration: 800 },
     *     { to: 2, duration: 1200 }
     *   ]
     * }, { loop: true });
     */
    keyframes(bodyIndex: number, keyframes: any, options?: {
        loop?: boolean | number;
        alternate?: boolean;
    }): any;
    /**
     * Create a timeline for a specific kinematic body
     * Automatically syncs to SAB on every update
     *
     * @param {number} bodyIndex - Index of the kinematic body
     * @param {Object} [defaults] - Default options for all animations in timeline
     * @param {number} [defaults.duration] - Default duration
     * @param {string} [defaults.ease] - Default easing
     * @param {boolean} [defaults.loop] - Loop the entire timeline
     * @param {Object} [initialValues] - Optional initial position { px, py, pz, qx, qy, qz, qw }
     * @returns {Object} Object with { timeline, target } for chaining
     *
     * @example
     * // NPC patrol path
     * const { timeline: tl, target } = animator.createTimelineFor(npcIndex, { loop: true }, { px: -5, pz: 8 });
     * tl.add(target, { px: 5, duration: 2000 })
     *   .add(target, { qy: 0.707, qw: 0.707, duration: 300 })
     *   .add(target, { pz: -5, duration: 2000 });
     */
    createTimelineFor(bodyIndex: number, defaults?: {
        duration?: number;
        ease?: string;
        loop?: boolean;
    }, initialValues?: any): any;
    /**
     * Create a raw timeline (no automatic SAB sync - for advanced usage)
     * Use createTimelineFor() instead for automatic SAB synchronization
     *
     * @param {Object} [defaults] - Default options for all animations in timeline
     * @returns {Object} Anime.js timeline instance
     * @deprecated Use createTimelineFor() for automatic SAB sync
     */
    createTimeline(defaults?: any): any;
    /**
     * Stop animation for a specific body
     * @param {number} bodyIndex - Index of the kinematic body
     */
    stop(bodyIndex: number): void;
    /**
     * Stop all animations
     */
    stopAll(): void;
    /**
     * Dispose of the animator and stop all animations
     */
    dispose(): void;
}
